const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'State of the Web 2020–2025'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Decorative accent bar on left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.15, h: 5.625,
    fill: { color: theme.accent }
  });

  // Small top accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 1.6, w: 1.2, h: 0.04,
    fill: { color: theme.accent }
  });

  // Main title
  slide.addText("State of the Web 2020–2025", {
    x: 0.6, y: 1.8, w: 8.5, h: 1.0,
    fontSize: 44, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "left"
  });

  // Subtitle
  slide.addText("Tracking Page Weight, Protocols & Security at Scale", {
    x: 0.6, y: 2.85, w: 8.5, h: 0.5,
    fontSize: 20, fontFace: "Arial",
    color: theme.light, bold: false, align: "left"
  });

  // Meta info: data source and date range
  slide.addText("HTTP Archive — State of the Web Report", {
    x: 0.6, y: 3.55, w: 8.5, h: 0.35,
    fontSize: 14, fontFace: "Arial",
    color: theme.light, bold: false, align: "left"
  });

  slide.addText("January 2020 – March 2026", {
    x: 0.6, y: 3.9, w: 8.5, h: 0.3,
    fontSize: 13, fontFace: "Arial",
    color: theme.accent, bold: false, align: "left"
  });

  // Audience tag pill
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.6, y: 4.45, w: 3.6, h: 0.38,
    fill: { color: theme.secondary },
    rectRadius: 0.19
  });
  slide.addText("Web Performance Engineers & Front-End Architects", {
    x: 0.6, y: 4.45, w: 3.6, h: 0.38,
    fontSize: 11, fontFace: "Arial",
    color: "FFFFFF", bold: false, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "0a0a0a",
    secondary: "0070F3",
    accent: "D4AF37",
    light: "f5f5f5",
    bg: "ffffff"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

const pptxgen = require("pptxgenjs");
const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';
pres.title = "State of the Web 2020–2025: HTTP Archive Trends in Page Weight, Protocols, and Security";
pres.author = "HTTP Archive Analysis";

const theme = {
  primary: "0a0a0a",
  secondary: "0070F3",
  accent: "D4AF37",
  light: "f5f5f5",
  bg: "ffffff"
};

for (let i = 1; i <= 8; i++) {
  const num = String(i).padStart(2, '0');
  const slideModule = require(`./slide-${num}.js`);
  slideModule.createSlide(pres, theme);
}

pres.writeFile({ fileName: './output/final_deck.pptx' });
